// Milky Nice (made with Fontself Maker), used for the YourDramaList logo, the opening animation and the
// page titles. Trimmed to letters, space and apostrophe (and without its color layer), compressed as
// WOFF2 so it loads quickly; served from this site.
const encoded="";
let bytes:Uint8Array|undefined;
export const LOGO_FONT_PATH="/assets/milky-nice-v2.woff2";
export function logoFont(){bytes??=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0));return new Response(bytes,{headers:{"content-type":"font/woff2","cache-control":"public,max-age=31536000,immutable","x-content-type-options":"nosniff"}});}
